import{_ as a,o as s,c as i,a7 as t}from"./chunks/framework.BJyR0VjM.js";const c=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/getting-started.md","filePath":"documentation/getting-started.md"}'),r={name:"documentation/getting-started.md"};function n(l,e,h,o,d,g){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting Started”">​</a></h1><p>This page walks you through setting up and running YggUtils for the first time.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to “Prerequisites”">​</a></h2><ul><li><strong>Java</strong> installed (use the same version your Minecraft server JAR requires)</li><li>Your Minecraft server <code>.jar</code> file present in the directory where you&#39;ll run YggUtils</li><li>A Yggdrasil-compatible authentication server URL</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to “Installation”">​</a></h2><p>Download the latest <code>YggUtils.jar</code> from the <a href="https://github.com/yggutils/yggutils/releases" target="_blank" rel="noreferrer">GitHub releases page</a> and place it in the same directory as your server JAR.</p><p>Your folder should look something like this:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/server</span></span>
<span class="line"><span>├── YggUtils.jar</span></span>
<span class="line"><span>├── server.jar          ← your Minecraft server</span></span>
<span class="line"><span>├── server.properties</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><h2 id="first-run" tabindex="-1">First Run <a class="header-anchor" href="#first-run" aria-label="Permalink to “First Run”">​</a></h2><p>Run YggUtils once to generate the default config:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YggUtils.jar</span></span></code></pre></div><p>Because no config file exists yet, YggUtils will create <code>YggUtils.yml</code> with empty values and exit:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[YggUtils] No configuration found. A default config has been generated: YggUtils.yml</span></span>
<span class="line"><span>[YggUtils] Please fill in &#39;authserver&#39; and &#39;serverfile&#39; before running again.</span></span></code></pre></div><h2 id="configure" tabindex="-1">Configure <a class="header-anchor" href="#configure" aria-label="Permalink to “Configure”">​</a></h2><p>Open <code>YggUtils.yml</code> and fill in both values:</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">authserver</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://your.auth.server</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">serverfile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">server.jar</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>authserver</code></td><td>The root URL of your Yggdrasil-compatible authentication server</td></tr><tr><td><code>serverfile</code></td><td>The filename of your Minecraft server JAR (relative to the working directory)</td></tr></tbody></table><h2 id="start-the-server" tabindex="-1">Start the Server <a class="header-anchor" href="#start-the-server" aria-label="Permalink to “Start the Server”">​</a></h2><p>Run YggUtils again:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YggUtils.jar</span></span></code></pre></div><p>YggUtils will silently launch your server with authlib-injector attached. All server output passes through to your console as normal.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li>Learn about <a href="/documentation/configuration">configuration options</a></li><li>Understand the <a href="/documentation/how-launching-works">launch process</a></li><li>See what happens on <a href="/documentation/auto-restart">crashes and restarts</a></li></ul>`,23)])])}const u=a(r,[["render",n]]);export{c as __pageData,u as default};
